-- W-C1 E1 reconciliation through the metric views (contract of 01-spec/oracle/metrics/W-C1.sql).
-- Generated by build_reconciliation_queries.py; edit the generator, not this file.
SELECT grain, measure, member_1, member_2, member_3, value
FROM (
  SELECT 'total_stock_group' AS grain, 'W-C1' AS measure, stock_group AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(stock_group_revenue_share) AS value
  FROM slc.semantic.wwi_sales_by_stock_group
  GROUP BY stock_group
  UNION ALL
  SELECT 'total_all_groups' AS grain, 'W-C1' AS measure, CAST(NULL AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, CAST(MEASURE(revenue_deduplicated) AS DOUBLE) / NULLIF(CAST(MEASURE(revenue_all_groups) AS DOUBLE), 0) AS value
  FROM slc.semantic.wwi_sales_by_stock_group
  UNION ALL
  SELECT 'year_stock_group' AS grain, 'W-C1' AS measure, CAST(calendar_year AS STRING) AS member_1, stock_group AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(stock_group_revenue_share) AS value
  FROM slc.semantic.wwi_sales_by_stock_group
  GROUP BY calendar_year, stock_group
  UNION ALL
  SELECT 'year_all_groups' AS grain, 'W-C1' AS measure, CAST(calendar_year AS STRING) AS member_1, CAST(NULL AS STRING) AS member_2, CAST(NULL AS STRING) AS member_3, CAST(MEASURE(revenue_deduplicated) AS DOUBLE) / NULLIF(CAST(MEASURE(revenue_all_groups) AS DOUBLE), 0) AS value
  FROM slc.semantic.wwi_sales_by_stock_group
  GROUP BY calendar_year
  UNION ALL
  SELECT 'fiscal_year_stock_group' AS grain, 'W-C1' AS measure, CAST(fiscal_year AS STRING) AS member_1, stock_group AS member_2, CAST(NULL AS STRING) AS member_3, MEASURE(stock_group_revenue_share) AS value
  FROM slc.semantic.wwi_sales_by_stock_group
  GROUP BY fiscal_year, stock_group
  UNION ALL
  SELECT 'year_sales_territory_stock_group' AS grain, 'W-C1' AS measure, CAST(calendar_year AS STRING) AS member_1, sales_territory AS member_2, stock_group AS member_3, MEASURE(stock_group_revenue_share) AS value
  FROM slc.semantic.wwi_sales_by_stock_group
  GROUP BY calendar_year, sales_territory, stock_group
  UNION ALL
  SELECT 'year_customer_category_stock_group' AS grain, 'W-C1' AS measure, CAST(calendar_year AS STRING) AS member_1, customer_category AS member_2, stock_group AS member_3, MEASURE(stock_group_revenue_share) AS value
  FROM slc.semantic.wwi_sales_by_stock_group
  GROUP BY calendar_year, customer_category, stock_group
) r
ORDER BY grain, measure, member_1 NULLS FIRST, member_2 NULLS FIRST, member_3 NULLS FIRST
